  "source": "def investigate(context, acquire):
    values = context.get("values", [])
    if not values:
        return 0

    def calc_p(x):
        return 2 * x * x * x - x * x + 2 * x

    contributions = []
    running_sum = 0
    for x in values:
        c = calc_p(x) + 1 * x * running_sum
        contributions.append(c)
        running_sum += x

    res_list = contributions
    for _ in range(3):
        new_res = []
        s = 0
        for v in res_list:
            s += v
            new_res.append(s)
        res_list = new_res

    return res_list[-1]",
